<?php

declare(strict_types=1);
namespace Ispluka\Controllers;
use Ispluka\Core\Http\Request;
use Ispluka\Core\Http\Response;
use Ispluka\Core\Network\PppoeActivityRepository;
use Ispluka\Core\Network\PppoeEnforcementAuditQuery;
use Ispluka\Core\Network\PppoeUsageReport;
use PDO;
final class MikrotikEnforcementAuditController
{
 public function __construct(private readonly PDO $pdo){}
 private function tenant(Request $r):int{return (int)($r->attribute('tenant_id')??0);}
 public function audit(Request $r):Response{$t=$this->tenant($r);$status=trim((string)($r->input('status')??''));$limit=(int)($r->input('limit')??50);$offset=(int)($r->input('offset')??0);return Response::json(['data'=>(new PppoeEnforcementAuditQuery($this->pdo))->list($t,$status!==''?$status:null,$limit,$offset)]);}
 public function summary(Request $r):Response{return Response::json(['data'=>(new PppoeEnforcementAuditQuery($this->pdo))->summary($this->tenant($r))]);}
 public function live(Request $r):Response{$tenant=$this->tenant($r);$router=(int)($r->input('router_id')??0);$username=trim((string)($r->input('username')??''));if($tenant<1||$router<1||$username==='')return Response::json(['error'=>['message'=>'Tenant, router_id and username are required.']],422);$row=(new PppoeActivityRepository($this->pdo))->find($tenant,$router,$username);if($row===null)return Response::json(['error'=>['message'=>'No activity snapshot found.']],404);$row['source']='activity_snapshot';$row['note']='Latest bounded MikroTik collection; this avoids per-user router polling.';return Response::json(['data'=>$row]);}
 public function reconciliation(Request $r):Response{$tenant=$this->tenant($r);if($tenant<1)return Response::json(['error'=>['message'=>'Tenant context required.']],403);$status=trim((string)($r->input('status')??''));$severity=trim((string)($r->input('severity')??''));$router=(int)($r->input('router_id')??0);$where=['tenant_id=:tenant'];$params=[':tenant'=>$tenant];if(in_array($status,['open','resolved'],true)){$where[]='status=:status';$params[':status']=$status;}if(in_array($severity,['critical','high','warning','info'],true)){$where[]='severity=:severity';$params[':severity']=$severity;}if($router>0){$where[]='router_id=:router';$params[':router']=$router;}$q=$this->pdo->prepare('SELECT id,router_id,username,finding_type,severity,message,details,status,first_seen_at,last_seen_at,resolved_at FROM pppoe_reconciliation_findings WHERE '.implode(' AND ',$where).' ORDER BY last_seen_at DESC LIMIT 500');$q->execute($params);return Response::json(['data'=>$q->fetchAll(PDO::FETCH_ASSOC)]);}
 public function usage(Request $r):Response{$tenant=$this->tenant($r);$router=(int)($r->input('router_id')??0);$username=trim((string)($r->input('username')??''));$from=trim((string)($r->input('from')??''));$to=trim((string)($r->input('to')??''));if($tenant<1||$router<1||$username===''||$from===''||$to==='')return Response::json(['error'=>['message'=>'Tenant, router_id, username, from and to are required.']],422);try{$fromTs=new \DateTimeImmutable($from);$toTs=new \DateTimeImmutable($to);}catch(\Throwable){return Response::json(['error'=>['message'=>'Invalid date range.']],422);}if($toTs<=$fromTs)return Response::json(['error'=>['message'=>'Invalid date range.']],422);$now=new \DateTimeImmutable('now');$min=$now->modify('-6 months');if($fromTs<$min)$fromTs=$min;if($toTs>$now)$toTs=$now;if($toTs<=$fromTs)return Response::json(['data'=>[]]);$data=(new PppoeUsageReport($this->pdo))->monthly($tenant,$router,$username,$fromTs->format('Y-m-d H:i:s'),$toTs->format('Y-m-d H:i:s'));return Response::json(['data'=>$data,'meta'=>['from'=>$fromTs->format(DATE_ATOM),'to'=>$toTs->format(DATE_ATOM),'retention_months'=>6]]);}
 public function page(Request $r):Response{return Response::text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/css/app.css"><title>MikroTik Audit</title><style>.wrap{max-width:1100px;margin:auto;padding:16px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.card{border:1px solid #e2e8f0;border-radius:14px;padding:14px;background:#fff}.list{display:grid;gap:10px;margin-top:12px}.muted{color:#64748b;font-size:13px}.live{margin-top:10px;padding:10px;border-radius:10px;background:#f8fafc}@media(max-width:700px){.grid{grid-template-columns:repeat(2,1fr)}}</style></head><body><main class="wrap" data-page="mikrotik-audit"><div style="display:flex;justify-content:space-between"><div><h1>MikroTik Audit</h1><div class="muted">ERP ↔ MikroTik reconciliation and PPPoE activity</div></div><a href="/">Dashboard</a></div><section class="grid" style="margin-top:12px"><div class="card"><div class="muted">Critical</div><strong data-stat="critical">0</strong></div><div class="card"><div class="muted">High</div><strong data-stat="high">0</strong></div><div class="card"><div class="muted">Warning</div><strong data-stat="warning">0</strong></div><div class="card"><div class="muted">Open</div><strong data-stat="open">0</strong></div></section><div style="margin-top:12px"><select id="status"><option value="">All</option><option value="open">Open</option><option value="resolved">Resolved</option></select> <select id="severity"><option value="">All severity</option><option value="critical">Critical</option><option value="high">High</option><option value="warning">Warning</option><option value="info">Info</option></select></div><section class="list" data-audit-list><div class="card muted">Loading…</div></section></main><script src="/js/pppoe-live-metrics.js" defer></script><script>document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('[data-page="mikrotik-audit"]'),list=root.querySelector('[data-audit-list]');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function load(){const q=new URLSearchParams();['status','severity'].forEach(k=>{const v=document.getElementById(k).value;if(v)q.set(k,v)});const res=await fetch('/api/networking/mikrotik/audit?'+q,{credentials:'same-origin',headers:{Accept:'application/json'}});const j=await res.json(),rows=j.data||[];const c={critical:0,high:0,warning:0,open:0};rows.forEach(r=>{if(c[r.severity]!=null)c[r.severity]++;if(r.status==='open')c.open++});Object.entries(c).forEach(([k,v])=>root.querySelector('[data-stat="'+k+'"]').textContent=v);list.innerHTML=rows.map((r,i)=>'<article class="card"><b>'+esc(r.username)+'</b> · '+esc(r.finding_type)+' · '+esc(r.severity)+'<p>'+esc(r.message)+'</p><div class="muted">Router #'+esc(r.router_id)+' · '+esc(r.status)+' · '+esc(r.last_seen_at)+'</div><div class="live" data-live>Live metrics: <button data-i="'+i+'">Load</button></div></article>').join('')||'<div class="card">No findings.</div>';list.querySelectorAll('[data-live] button').forEach(b=>b.onclick=async()=>{const r=rows[+b.dataset.i],u=new URLSearchParams({router_id:r.router_id,username:r.username}),x=await fetch('/api/networking/mikrotik/pppoe/live?'+u,{credentials:'same-origin',headers:{Accept:'application/json'}}),d=await x.json();b.parentElement.textContent=d.data?`IP: ${esc(d.data.active_ip||'—')} · Rx: ${esc(d.data.rx_rate_bps??'—')} bps · Tx: ${esc(d.data.tx_rate_bps??'—')} bps · Updated: ${esc(d.data.updated_at||'—')}`:(d.error?.message||'Unavailable')})}load();document.querySelectorAll('select').forEach(e=>e.onchange=load)});</script></body></html>');}
}
